// Vorlage je Art: neue_aufgabe (Aufgabe zugewiesen) oder chat_erwaehnung (im Team-Chat markiert, Haken beim Senden). Beide: {{1}} Empfänger, {{2}} von, {{3}} Titel.
const VORLAGE = { neue_aufgabe: 'neue_aufgabe', chat_erwaehnung: 'chat_erwaehnung' };
const L = ($input.first().json.liste || []).filter(x => x && x.id && /^\d{8,15}$/.test(String(x.wa || '')));
const kurz = (s, n) => { s = String(s || '').replace(/[\n\t]+/g, ' ').replace(/ {4,}/g, '   ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : (s || '–'); };
return L.map(x => ({ json: { id: x.id, wa_body: { messaging_product: 'whatsapp', to: String(x.wa), type: 'template', template: { name: VORLAGE[x.art] || 'neue_aufgabe', language: { code: 'de' }, components: [{ type: 'body', parameters: [{ type: 'text', text: kurz(x.an_name, 40) }, { type: 'text', text: kurz(x.von_name, 40) }, { type: 'text', text: kurz(x.titel, 200) }] }] } } } }));
